'use strict';
function fruitBudget(experience,price,count){if(!Number.isSafeInteger(experience)||experience<0||experience>1000000000)throw Error('剩余经验请填 0–10亿 的整数。');if(!Number.isFinite(price)||price<0||price>1000000)throw Error('单价请填 0–100万（单位：万两）之间的数字。');if(!Number.isInteger(count)||count<1||count>5)throw Error('角色数量请填 1–5 的整数。');const fruit=Math.ceil(experience/150);return{fruit,totalFruit:fruit*count,totalCost:fruit*count*price,surplus:fruit*150-experience}}
const teamPlans={attack:{title:'5 只攻宠：集中补刀、打主怪',body:'人物已经能把大部分小怪清掉时，攻宠可以接着集中打主怪或残血目标。全力、血攻的选择还得看宝宝是否容易被打飞，不是力量加得越多就一定越省回合。',note:'如果人物秒完仍有一大片小怪，五只单体攻宠未必能全部收干净。先看剩怪数、速度和实际集火，不必只因为攻宠便宜就统一配置。'},magic:{title:'5 只群法须弥：补群体伤害',body:'小怪普遍残血、需要宝宝再补一轮群法时，可以比较群法须弥。逐只核对实际法术、须弥、增伤技能、魔力、速度与对应宠修。',note:'五只法宠的预算、动画时间和打主怪能力都要考虑。先拿现有法宠试清怪效果，再决定是否需要把五只都换掉。'},mixed:{title:'3 只攻宠 + 2 只法宠：可以先这样过渡',body:'让法宠补群体伤害，攻宠负责残血与主怪。这是便于逐步调整的一种方案，不是固定最优比例。现有宝宝还能用，就先留着，哪一部分不足再补哪一部分。',note:'先看两只法宠实际能收掉多少小怪，攻宠有没有集中补对目标。小怪还剩很多时，也要回头查人物固伤，不能只靠增加宝宝预算。'}};
if(typeof module!=='undefined')module.exports={fruitBudget,teamPlans};
if(typeof document!=='undefined'){
const el=id=>document.getElementById(id),fmt=n=>n.toLocaleString('zh-CN',{maximumFractionDigits:2});
function updateFruit(){try{const values=['fruit-exp','fruit-price','fruit-count'].map(id=>{const raw=el(id).value;if(!raw.trim())throw Error('请把经验、单价和角色数量填完整。');return Number(raw)});const r=fruitBudget(...values);el('fruit-error').textContent='';el('fruit-results').innerHTML='<div class="result"><strong>'+fmt(r.fruit)+' 颗</strong><span>每角色需要的修炼果</span></div><div class="result"><strong>'+fmt(r.totalFruit)+' 颗</strong><span>'+values[2]+' 个角色共需修炼果</span></div><div class="result"><strong>'+fmt(r.totalCost)+' 万两</strong><span>预计总支出</span></div>';el('fruit-results').dataset.surplus=r.surplus}catch(e){el('fruit-error').textContent=e.message;el('fruit-results').replaceChildren()}}
document.querySelectorAll('#fruit-exp,#fruit-price,#fruit-count').forEach(e=>e.addEventListener('input',updateFruit));updateFruit();
function showTeam(key){const p=teamPlans[key];el('team-title').textContent=p.title;el('team-body').textContent=p.body;el('team-note').textContent=p.note;document.querySelectorAll('[data-team]').forEach(e=>{const on=e.dataset.team===key;e.classList.toggle('selected',on);e.setAttribute('aria-selected',String(on))})}document.querySelectorAll('[data-team]').forEach(e=>e.onclick=()=>showTeam(e.dataset.team));showTeam('mixed');
const growthAdvice={attack:'先算补这两个技能要花多少，还有打书掉技能的风险。攻资高是优点，但第一次买任务成品，通常更需要买来就能用。',growth:'成长有用，但不能只凭它下结论。要结合攻资、等级、加点、装备和实际攻击，再看这只成品能否完成任务。',balanced:'这是新手挑成品时比较稳妥的起点。再检查速度、生存、内丹和装备，总价合适、买来能正常刷任务，比单项数字漂亮更实在。'};document.querySelectorAll('[data-choice]').forEach(e=>e.onclick=()=>{el('growth-advice').textContent=growthAdvice[e.dataset.choice];document.querySelectorAll('[data-choice]').forEach(b=>b.classList.toggle('selected',b===e))});
const checks=['核对是宝宝、变异或其他类型，不把纯野生当普通宝宝买','确认携带条件、召唤兽等级和人物等级相符','看对应资质、成长、加点与最终面板','确认核心技能齐全，没有影响用途的冲突技能','检查内丹种类、层数和可用格数','检查进阶、灵性与特性情况','核对三件宝宝装备与套装是否生效','确认速度符合自己的任务和出手安排','把售价及后续技能、内丹、装备和宠修预算一起算清楚'];
let state=[];try{const stored=JSON.parse(localStorage.getItem('lesson4-pet-checks')||'[]');if(Array.isArray(stored))state=checks.map((_,i)=>stored[i]===true)}catch{}el('pet-checklist').innerHTML=checks.map((text,i)=>'<p><label><input type="checkbox" data-pet-check="'+i+'" '+(state[i]?'checked':'')+'> '+text+'</label></p>').join('');function checkStatus(){el('pet-check-status').textContent='已检查 '+checks.filter((_,i)=>state[i]).length+' / '+checks.length+' 项'}function saveChecks(){try{localStorage.setItem('lesson4-pet-checks',JSON.stringify(state))}catch{}checkStatus()}document.querySelectorAll('[data-pet-check]').forEach(e=>e.onchange=()=>{state[+e.dataset.petCheck]=e.checked;saveChecks()});el('pet-check-reset').onclick=()=>{state=checks.map(()=>false);document.querySelectorAll('[data-pet-check]').forEach(e=>e.checked=false);saveChecks()};checkStatus();
let done=false;try{done=localStorage.getItem('lesson4-complete')==='1'}catch{}function paintDone(){el('complete').textContent=done?'第四课已学完 ✓ · 点击重置':'标记第四课已学完 ✓'}el('complete').onclick=()=>{done=!done;try{localStorage.setItem('lesson4-complete',done?'1':'0')}catch{}paintDone()};paintDone();const sections=[...document.querySelectorAll('section')];function progress(){const p=Math.min(100,Math.round(window.scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight)*100));el('progress').value=p;el('progress-label').textContent='阅读进度 '+p+'%';let id=sections[0].id;sections.forEach(s=>{if(s.getBoundingClientRect().top<innerHeight*.35)id=s.id});document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+id))}addEventListener('scroll',progress,{passive:true});progress();
}
